import reliquary.item.RendingGaleItem;
import reliquary.reference.Config;

import java.util.List;

public class PedestalRendingGaleWrapper implements IPedestalActionItemWrapper {
	private static final int SECONDS_BETWEEN_BUFF_CHECKS = 2;
	private static final int TICKS_BETWEEN_PUSH_PULL_CHECKS = 1;

	private int buffCheckCoolDown;
	private int pushPullCheckCoolDown;

	@Override
	public void update(ItemStack stack, Level level, IPedestal pedestal) {
		BlockPos pos = pedestal.getBlockPosition();
		RendingGaleItem rendingGale = (RendingGaleItem) stack.getItem();
		if (rendingGale.getMode(stack) == RendingGaleItem.Mode.FLIGHT) {
			if (buffCheckCoolDown <= 0) {
				buffPlayersWithFlight(stack, level, pos);
				buffCheckCoolDown = SECONDS_BETWEEN_BUFF_CHECKS * 20;
			} else {
				buffCheckCoolDown--;
			}
		} else if (rendingGale.getMode(stack) == RendingGaleItem.Mode.PUSH) {
			if (pushPullCheckCoolDown <= 0) {
				pushEntities(stack, level, pos, rendingGale, false);
				pushPullCheckCoolDown = TICKS_BETWEEN_PUSH_PULL_CHECKS;
			} else {
				pushPullCheckCoolDown--;
			}
		} else if (rendingGale.getMode(stack) == RendingGaleItem.Mode.PULL) {
			if (pushPullCheckCoolDown <= 0) {
				pushEntities(stack, level, pos, rendingGale, true);
				pushPullCheckCoolDown = TICKS_BETWEEN_PUSH_PULL_CHECKS;
			} else {
				pushPullCheckCoolDown--;
			}
		}
	}

	private void pushEntities(ItemStack stack, Level level, BlockPos pos, RendingGaleItem rendingGale, boolean b) {
		rendingGale.doRadialPush(level, pos.getX(), pos.getY(), pos.getZ(), null, b);
		ModItems.RENDING_GALE.get().useCharge(stack,
				(int) (TICKS_BETWEEN_PUSH_PULL_CHECKS / 20F * Config.COMMON.items.rendingGale.pedestalCostPerSecond.get()));
	}

	private void buffPlayersWithFlight(ItemStack stack, Level level, BlockPos pos) {
		int flightRange = Config.COMMON.items.rendingGale.pedestalFlightRange.get();
		int flightChargeCost = SECONDS_BETWEEN_BUFF_CHECKS * Config.COMMON.items.rendingGale.pedestalCostPerSecond.get();
		RendingGaleItem rendingGale = (RendingGaleItem) stack.getItem();

		List<Player> players = level.getEntitiesOfClass(Player.class, new AABB((double) pos.getX() - flightRange, (double) pos.getY() - flightRange,
				(double) pos.getZ() - flightRange, (double) pos.getX() + flightRange, (double) pos.getY() + flightRange, (double) pos.getZ() + flightRange));

		if (!players.isEmpty()
				&& (flightChargeCost == 0 || rendingGale.getTotalCharge(stack) >= flightChargeCost && rendingGale.useCharge(stack, flightChargeCost))) {
			for (Player player : players) {
				player.addEffect(new MobEffectInstance(ModEffects.FLIGHT, 20 * 20, 0, false, false, true));
			}
		}
	}

	@Override
	public void onRemoved(ItemStack stack, Level level, IPedestal pedestal) {
		// noop
	}

	@Override
	public void stop(ItemStack stack, Level level, IPedestal pedestal) {
		// noop
	}
}

				? existingFeatherCount + Math.min(chargeToAdd, Math.max(maxFeatherCount - existingFeatherCount, 0))
				: Math.max(0, existingFeatherCount + chargeToAdd);
		runOnHandler(containerStack, handler -> handler.setStackInSlot(0, featherCount == 0 ? ItemStack.EMPTY : new ItemStack(Items.FEATHER, featherCount)));
	}

	@Override
	public int getStoredCharge(ItemStack containerStack, int slot) {
		return getFeatherCount(containerStack);
	}

	@Override
	protected int getSlotWorth(int slot) {
		return slot == 0 ? getFeathersWorth() : 0;
	}

	@Override
	protected int getContainerSlotLimit(int slot) {
		return getChargeLimit() / getFeathersWorth();
	}

	@Override
	public void onUseTick(Level level, LivingEntity livingEntity, ItemStack rendingGale, int remainingUseDuration) {
		if (!(livingEntity instanceof Player player)) {
			return;
		}

		Mode mode = getMode(rendingGale);
		int chargeCost = mode == Mode.BOLT ? getBoltChargeCost() : getChargeCost();
		if (getTotalCharge(rendingGale) < chargeCost) {
			player.releaseUsingItem();
			return;
		}

		if (mode == Mode.BOLT) {
			if (remainingUseDuration % 8 == 0) {
				spawnBolt(rendingGale, player);
			}
		} else if (player.level().isClientSide || useCharge(rendingGale, FIRST_SLOT, chargeCost)) {
			if (mode == Mode.FLIGHT) {
				attemptFlight(player);
				spawnFlightParticles(player.level(), player.getX(), player.getY() + player.getEyeHeight(), player.getZ(), player);
			} else if (mode == Mode.PUSH) {
				doRadialPush(player.level(), player.getX(), player.getY(), player.getZ(), player, false);
			} else if (mode == Mode.PULL) {
				doRadialPush(player.level(), player.getX(), player.getY(), player.getZ(), player, true);
			}
		}
	}

	private void spawnBolt(ItemStack rendingGale, Player player) {
		HitResult rayTraceResult = player.pick(getBoltTargetRange(), 1, true);
		if (rayTraceResult.getType() == HitResult.Type.BLOCK) {
			BlockHitResult blockRayTraceResult = (BlockHitResult) rayTraceResult;
			BlockPos pos = blockRayTraceResult.getBlockPos();
			int attemptedY = pos.getY();
			if (!player.level().isRainingAt(pos)) {
				attemptedY++;
			}
			if (!player.level().isClientSide && player.level().isRainingAt(new BlockPos(pos.getX(), attemptedY, pos.getZ()))) {
				LightningBolt bolt = EntityType.LIGHTNING_BOLT.create(player.level());
				if (bolt != null && useCharge(rendingGale, FIRST_SLOT, getBoltChargeCost())) {
					bolt.moveTo(pos.getX(), pos.getY(), pos.getZ());
					player.level().addFreshEntity(bolt);
				}
			}
		}
	}

	public boolean hasFlightCharge(ItemStack stack) {
		return getTotalCharge(stack) >= getChargeCost();
	}

	public int getFeatherCount(ItemStack rendingGale) {
		return getFromHandler(rendingGale, handler -> handler.getCountInSlot(0));
	}

	public int getMigratedFeatherCount(ItemStack rendingGale) {
		getTotalCharge(rendingGale);
		return getFeatherCount(rendingGale);
	}

	public void doRadialPush(Level level, double posX, double posY, double posZ, @Nullable Player player, boolean pull) {
		// push effect free at the moment, if you restore cost, remember to change this to getFeatherCount
		spawnRadialHurricaneParticles(level, posX, posY, posZ, player, pull);
		if (level.isClientSide) {
			return;
		}

		double lowerX = posX - getRadialPushRadius();
		double lowerY = posY - getRadialPushRadius() / 5D;
		double lowerZ = posZ - getRadialPushRadius();
		double upperX = posX + getRadialPushRadius();
		double upperY = posY + getRadialPushRadius() / 5D;
		double upperZ = posZ + getRadialPushRadius();

		List<Entity> entities = level.getEntitiesOfClass(Entity.class, new AABB(lowerX, lowerY, lowerZ, upperX, upperY, upperZ),
				e -> (e instanceof Mob || e instanceof Projectile));

		for (Entity entity : entities) {
			double distance = getDistanceToEntity(posX, posY, posZ, entity);
			if (distance < getRadialPushRadius()) {
				if (isBlacklistedEntity(entity) || entity.equals(player)) {
					continue;
				}

				Vec3 pushVector;
				if (pull) {
					pushVector = new Vec3(posX - entity.getX(), posY - entity.getY(), posZ - entity.getZ());
				} else {
					pushVector = new Vec3(entity.getX() - posX, entity.getY() - posY, entity.getZ() - posZ);
				}
				pushVector = pushVector.normalize();
				entity.move(MoverType.PLAYER, new Vec3(0.0D, 0.2D, 0.0D));
				entity.move(MoverType.PLAYER, new Vec3(pushVector.x, Math.min(pushVector.y, 0.1D) * 1.5D, pushVector.z));
			}
		}
	}

	private boolean isBlacklistedEntity(Entity entity) {
		String entityName = RegistryHelper.getRegistryName(entity).toString();
		return isBlacklistedLivingEntity(entity, entityName)
				|| Config.COMMON.items.rendingGale.canPushProjectiles.get() && isBlacklistedProjectile(entity, entityName);
	}

	private boolean isBlacklistedProjectile(Entity entity, String entityName) {
		return entity instanceof Projectile && Config.COMMON.items.rendingGale.pushableProjectilesBlacklist.get().contains(entityName);
	}

	private boolean isBlacklistedLivingEntity(Entity entity, String entityName) {
		return entity instanceof Mob && Config.COMMON.items.rendingGale.pushableEntitiesBlacklist.get().contains(entityName);
	}

	private float getDistanceToEntity(double posX, double posY, double posZ, Entity entityIn) {
		float f = (float) (posX - entityIn.getX());
		float f1 = (float) (posY - entityIn.getY());
		float f2 = (float) (posZ - entityIn.getZ());
		return Mth.sqrt(f * f + f1 * f1 + f2 * f2);
	}

	private void spawnFlightParticles(Level level, double x, double y, double z, Player player) {
		Vec3 lookVector = player.getLookAngle();

		BlockParticleOption blockParticleData = new BlockParticleOption(ParticleTypes.BLOCK, Blocks.SNOW_BLOCK.defaultBlockState());

		// spawn a whole mess of particles every tick.
		for (int i = 0; i < 8; ++i) {
			float randX = 10F * (level.random.nextFloat() - 0.5F);
			float randY = 10F * (level.random.nextFloat() - 0.5F);
			float randZ = 10F * (level.random.nextFloat() - 0.5F);

			level.addParticle(blockParticleData, x + randX + lookVector.x * 20, y + randY + lookVector.y * 20, z + randZ + lookVector.z * 20, -lookVector.x * 5,
					-lookVector.y * 5, -lookVector.z * 5);
		}
	}

	private void spawnRadialHurricaneParticles(Level level, double posX, double posY, double posZ, @Nullable Player player, boolean pull) {
		BlockParticleOption blockParticleData = new BlockParticleOption(ParticleTypes.BLOCK, Blocks.SNOW_BLOCK.defaultBlockState());

		// spawn a whole mess of particles every tick.
		for (int i = 0; i < 3; ++i) {
			float randX = level.random.nextFloat() - 0.5F;
			float randZ = level.random.nextFloat() - 0.5F;
			float motX = randX * 10F;
			float motZ = randZ * 10F;
			if (pull) {
				randX *= 10F;
				randZ *= 10F;
				motX *= -1F;
				motZ *= -1F;
			}

			double posYAdjusted = player == null ? posY : (posY + player.getEyeHeight()) - (player.getBbHeight() / 2);

			level.addParticle(blockParticleData, posX + randX, posYAdjusted, posZ + randZ, motX, 0.0D, motZ);
		}
	}

	public enum Mode implements StringRepresentable {
		FLIGHT, PUSH, PULL, BOLT;

		public static final Codec<Mode> CODEC = StringRepresentable.fromEnum(Mode::values);
		public static final StreamCodec<FriendlyByteBuf, Mode> STREAM_CODEC = NeoForgeStreamCodecs.enumCodec(Mode.class);

		@Override
		public String getSerializedName() {
			return name();
		}

		public Mode next() {
			return VALUES[(ordinal() + 1) % VALUES.length];
		}

		public Mode previous() {
			return VALUES[Math.floorMod(ordinal() - 1, VALUES.length)];
		}

		private static final Mode[] VALUES;

		static {
			ImmutableMap.Builder<String, Mode> builder = new ImmutableMap.Builder<>();
			for (Mode value : values()) {
				builder.put(value.getSerializedName(), value);
			}
			VALUES = values();
		}
	}
}

package reliquary.potions;

import net.minecraft.network.protocol.game.ClientboundPlayerAbilitiesPacket;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.effect.MobEffect;
import net.minecraft.world.effect.MobEffectCategory;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.ai.attributes.AttributeInstance;
import net.minecraft.world.entity.ai.attributes.AttributeMap;
import net.minecraft.world.entity.player.Player;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.common.NeoForgeMod;
import net.neoforged.neoforge.event.entity.living.MobEffectEvent;
import org.jetbrains.annotations.Nullable;
import reliquary.init.ModEffects;

public class FlightEffect extends MobEffect {

	public FlightEffect() {
		super(MobEffectCategory.BENEFICIAL, 0xFFFFFF);
		NeoForge.EVENT_BUS.addListener(this::onEffectExpired);
		NeoForge.EVENT_BUS.addListener(this::onEffectRemoved);
	}

	@Override
	public boolean shouldApplyEffectTickThisTick(int duration, int amplifier) {
		return true;
	}

	@Override
	public boolean applyEffectTick(LivingEntity livingEntity, int amplifier) {
		if (livingEntity.level().isClientSide) {
			return true;
		}

		if (!(livingEntity instanceof Player player)) {
			return false;
		}

		AttributeInstance creativeFlightAttribute = player.getAttribute(NeoForgeMod.CREATIVE_FLIGHT);
		if (creativeFlightAttribute != null && creativeFlightAttribute.getValue() == 0) {
			creativeFlightAttribute.setBaseValue(1);
			((ServerPlayer) player).connection.send(new ClientboundPlayerAbilitiesPacket(player.getAbilities()));
		}
		player.fallDistance = 0;
		return true;
	}

	@Override
	public void removeAttributeModifiers(AttributeMap attributeMap) {
		super.removeAttributeModifiers(attributeMap);
	}

	private void onEffectExpired(MobEffectEvent.Expired event) {
		removeFlight(event.getEntity(), event.getEffectInstance());
	}

	private void onEffectRemoved(MobEffectEvent.Remove event) {
		removeFlight(event.getEntity(), event.getEffectInstance());
	}

	private static void removeFlight(LivingEntity entity, @Nullable MobEffectInstance effectInstance) {
		if (effectInstance == null || !effectInstance.getEffect().value().equals(ModEffects.FLIGHT.value())) {
			return;
		}

		if (!(entity instanceof ServerPlayer serverPlayer)) {
			return;
		}

		if (!serverPlayer.isCreative()) {
			AttributeInstance creativeFlightAttribute = serverPlayer.getAttribute(NeoForgeMod.CREATIVE_FLIGHT);
			if (creativeFlightAttribute != null) {
				creativeFlightAttribute.setBaseValue(0);
			}
			serverPlayer.getAbilities().flying = false;
			serverPlayer.connection.send(new ClientboundPlayerAbilitiesPacket(serverPlayer.getAbilities()));
		}
	}
}

